def compute(vars):
    allowance = vars["v1"]
    receivables = vars["v2"]
    if receivables == 0:
        return None

    value = (allowance / receivables) * 100
    return {
        "value": value,
        "trace": {
            "allowance": allowance,
            "receivables": receivables,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
